382	    /// Zero all key-material related to the peer
383	    pub fn zero_keys(&self) {
384	        log::trace!("peer.zero_keys");
385	
386	        let mut release: Vec<u32> = Vec::with_capacity(3);
387	        let mut keys = self.peer.keys.lock();
388	
389	        // update key-wheel
390	
391	        if let Some(k) = mem::replace(&mut keys.next, None) {
392	            release.push(k.local_id())
393	        }
394	        if let Some(k) = mem::replace(&mut keys.current, None) {
395	            release.push(k.local_id())
396	        }
397	        if let Some(k) = mem::replace(&mut keys.previous, None) {
398	            release.push(k.local_id())
399	        }
400	        keys.retired.extend(&release[..]);
401	
402	        // update inbound "recv" map
403	        {
404	            let mut recv = self.peer.device.recv.write();
405	            for id in release {
406	                recv.remove(&id);
407	            }
408	        }
409	
410	        // clear encryption state
411	        *self.peer.enc_key.lock() = None;
412	    }
413	
414	    pub fn down(&self) {
415	        self.zero_keys();
416	    }
417	
418	    pub fn up(&self) {}
419	
420	    /// Add a new keypair
421	    ///
422	    /// # Arguments
423	    ///
424	    /// - new: The new confirmed/unconfirmed key pair
425	    ///
426	    /// # Returns
427	    ///
428	    /// A vector of ids which has been released.
429	    /// These should be released in the handshake module.
430	    ///
431	    /// # Note
432	    ///
433	    /// The number of ids to be released can be at most 3,
434	    /// since the only way to add additional keys to the peer is by using this method
435	    /// and a peer can have at most 3 keys allocated in the router at any time.
436	    pub fn add_keypair(&self, new: KeyPair) -> Vec<u32> {
437	        log::trace!("Router, add_keypair: {:?}", new);
438	
439	        let initiator = new.initiator;
440	        let release = {
441	            let new = Arc::new(new);
442	            let mut keys = self.peer.keys.lock();
443	            let mut release = mem::replace(&mut keys.retired, vec![]);
444	
445	            // update key-wheel
446	            if new.initiator {
447	                // start using key for encryption
448	                *self.peer.enc_key.lock() = Some(EncryptionState::new(&new));
449	
450	                // move current into previous
451	                keys.previous = keys.current.as_ref().cloned();
452	                keys.current = Some(new.clone());
453	            } else {
454	                // store the key and await confirmation
455	                keys.previous = keys.next.as_ref().cloned();
456	                keys.next = Some(new.clone());
457	            };
458	
459	            // update incoming packet id map
460	            {
461	                log::trace!("peer.add_keypair: updating inbound id map");
462	                let mut recv = self.peer.device.recv.write();
463	
464	                // purge recv map of previous id
465	                if let Some(k) = &keys.previous {
466	                    recv.remove(&k.local_id());
467	                    release.push(k.local_id());
468	                }
469	
470	                // map new id to decryption state
471	                debug_assert!(!recv.contains_key(&new.recv.id));
472	                recv.insert(
473	                    new.recv.id,
474	                    Arc::new(DecryptionState::new(self.peer.clone(), &new)),
475	                );
476	            }
477	            release
478	        };
479	
480	        // schedule confirmation
481	        if initiator {
482	            debug_assert!(self.peer.enc_key.lock().is_some());
483	            log::trace!("peer.add_keypair: is initiator, must confirm the key");
484	            // attempt to confirm using staged packets
485	            if !self.peer.send_staged() {
486	                // fall back to keepalive packet
487	                self.send_keepalive();
488	                log::debug!("peer.add_keypair: keepalive for confirmation",);
489	            }
490	            log::trace!("peer.add_keypair: key attempted confirmed");
491	        }
492	
493	        debug_assert!(
494	            release.len() <= 3,
495	            "since the key-wheel contains at most 3 keys"
496	        );
497	        release
498	    }
499	
500	    pub fn send_keepalive(&self) {
501	        log::trace!("peer.send_keepalive");
502	        self.peer.send(vec![0u8; SIZE_MESSAGE_PREFIX], false)
503	    }
504	
505	    /// Map a subnet to the peer
506	    ///
507	    /// # Arguments
508	    ///
509	    /// - `ip`, the mask of the subnet
510	    /// - `masklen`, the length of the mask
511	    ///
512	    /// # Note
513	    ///
514	    /// The `ip` must not have any bits set right of `masklen`.
515	    /// e.g. `192.168.1.0/24` is valid, while `192.168.1.128/24` is not.
516	    ///
517	    /// If an identical value already exists as part of a prior peer,
518	    /// the allowed IP entry will be removed from that peer and added to this peer.
519	    pub fn add_allowed_ip(&self, ip: IpAddr, masklen: u32) {
520	        self.peer
521	            .device
522	            .table
523	            .insert(ip, masklen, self.peer.clone())
524	    }
525	
526	    /// List subnets mapped to the peer
527	    ///
528	    /// # Returns
529	    ///
530	    /// A vector of subnets, represented by as mask/size
531	    pub fn list_allowed_ips(&self) -> Vec<(IpAddr, u32)> {
532	        self.peer.device.table.list(&self.peer)
533	    }
534	
535	    /// Clear subnets mapped to the peer.
536	    /// After the call, no subnets will be cryptkey routed to the peer.
537	    /// Used for the UAPI command "replace_allowed_ips=true"
538	    pub fn remove_allowed_ips(&self) {
539	        self.peer.device.table.remove(&self.peer)
540	    }
541	
542	    pub fn clear_src(&self) {
543	        if let Some(e) = (*self.peer.endpoint.lock()).as_mut() {
544	            e.clear_src()
545	        }
546	    }
